const SEG_REGISTRO_RECIENTE_MIN = 10;
const SEG_CUOTA_PRIVADA_MB = 1100;
const SEG_DIAS_TIENDA_HABITUAL = 14;

function _segNavegacionPrivada(payload) {
  const cuota = Number(payload && payload.diag && payload.diag.cuota_mb) || 0;
  return /iPhone|iPad/.test(String((payload && payload.user_agent) || "")) && cuota > 0 && cuota <= SEG_CUOTA_PRIVADA_MB;
}

function _segUbicacionRequerida(payload, kiosco) {
  if (kiosco) return null;
  const idTienda = String(payload.id_tienda || "").toUpperCase();
  if (!idTienda || /-(RES|TEL)$/.test(idTienda)) return null;
  const lat = parseFloat(payload.lat);
  const lng = parseFloat(payload.lng);
  if (!isNaN(lat) && !isNaN(lng)) return null;
  return { ok: false, codigo: "UBICACION_REQUERIDA", mensaje: "Para marcar con la tarjeta necesitamos la ubicación de tu celular. Activala y volvé a intentarlo." };
}

function _segFilasDispositivo(ss) {
  const hoja = ss.getSheetByName("Dispositivos");
  return hoja && hoja.getLastRow() > 1 ? hoja.getRange(2, 1, hoja.getLastRow() - 1, 8).getValues() : [];
}

function _segActivo(v) {
  return v === true || String(v).toUpperCase() === "TRUE";
}

function _segDesactivarAnteriores(ss, id, token) {
  const hoja = ss.getSheetByName("Dispositivos");
  let desactivados = 0;
  _segFilasDispositivo(ss).forEach((f, i) => {
    if (String(f[1]) !== String(id) || String(f[0]) === String(token) || !_segActivo(f[7])) return;
    hoja.getRange(i + 2, 8).setValue(false);
    desactivados++;
  });
  return desactivados;
}

function _segTiendaHabitual(ss, id, fecha) {
  const horario = _buscarHorario(ss, id, fecha);
  if (horario && horario.id_tienda && (horario.estado === "TRABAJA" || horario.estado === "TRABAJA_SIN_HORA")) return horario.id_tienda;
  const desde = Date.now() - SEG_DIAS_TIENDA_HABITUAL * 86400000;
  const conteo = {};
  _marcasRecientes(ss, 30000).forEach(m => {
    if (String(m[2]) !== String(id) || m[13] !== "OK" || !m[0] || new Date(m[0]).getTime() < desde) return;
    const t = String(m[5]);
    if (/-(RES|TEL)$/.test(t)) return;
    conteo[t] = (conteo[t] || 0) + 1;
  });
  return Object.keys(conteo).sort((a, b) => conteo[b] - conteo[a])[0] || "";
}

function _segRevisarRegistro(ss, payload) {
  try {
    const idTienda = String(payload.id_tienda || "").toUpperCase();
    if (!idTienda || /-(RES|TEL)$/.test(idTienda)) return;
    const colaboradora = _buscarColaboradoraPorToken(ss, payload.token);
    const tienda = _buscarTienda(ss, idTienda);
    if (!colaboradora || !tienda || _impEsRuta(ss, colaboradora)) return;
    const fecha = _formatFecha(_fechaEnTimezone(new Date(), tienda.timezone));
    const habitual = _segTiendaHabitual(ss, colaboradora.id, fecha);
    if (!habitual || habitual === idTienda) return;
    const otra = _buscarTienda(ss, habitual);
    const hora = _horaEnTimezone(new Date(), tienda.timezone);
    _ctlMarcaEnRevision(ss, fecha, colaboradora, tienda, "REGISTRO_OTRA_TIENDA", "",
      "Registro " + String(hora).slice(0, 5) + " en " + tienda.nombre,
      "Registró un celular en " + tienda.nombre + ", pero hoy le corresponde " + (otra ? otra.nombre : habitual) + ". Confirmá que fue ella.", "Pendiente");
  } catch (err) {
    _logError("Seguridad", "_segRevisarRegistro", "AVISO", String(err), String(err.stack || ""));
  }
}

function _segRevisarMarca(ss, payload, resultado) {
  try {
    const disp = _filaDispositivo(ss, payload.token);
    if (!disp) return;
    const registro = disp.valores[5] instanceof Date ? disp.valores[5] : new Date(disp.valores[5]);
    const transcurrido = Date.now() - registro.getTime();
    if (isNaN(transcurrido) || transcurrido > SEG_REGISTRO_RECIENTE_MIN * 60000) return;
    const id = String(disp.valores[1]);
    const anteriores = _segFilasDispositivo(ss).some(f => String(f[1]) === id && String(f[0]) !== String(payload.token));
    if (!anteriores) return;
    const colaboradora = _buscarColaboradoraPorToken(ss, payload.token);
    const tienda = _buscarTienda(ss, String(payload.id_tienda || "").toUpperCase());
    if (!colaboradora || !tienda) return;
    const tipo = String(resultado.tipo_marca || "");
    const hora = String(resultado.hora_servidor || "").slice(0, 5);
    const minutos = Math.max(0, Math.round(transcurrido / 60000));
    _ctlMarcaEnRevision(ss, String(resultado.fecha), colaboradora, tienda, "REGISTRO_RECIENTE", tipo,
      (CTL_NOMBRE_MARCA[tipo] || tipo) + " " + hora + " (celular registrado hace " + minutos + " min)",
      "Marcó con un celular que se registró minutos antes. Confirmá que fue ella.", "Pendiente");
  } catch (err) {
    _logError("Seguridad", "_segRevisarMarca", "AVISO", String(err), String(err.stack || ""));
  }
}
